  course_id TEXT NOT NULL REFERENCES beam_courses(id),
  previous_reviewer_id TEXT NOT NULL REFERENCES beam_members(id),
  reviewer_id TEXT NOT NULL REFERENCES beam_members(id),
  reason TEXT NOT NULL,
  changed_by TEXT NOT NULL REFERENCES beam_members(id),
  changed_at INTEGER NOT NULL
);
CREATE INDEX beam_reviewer_changes_course ON beam_reviewer_changes(course_id);
ALTER TABLE beam_courses ADD COLUMN self_review INTEGER NOT NULL DEFAULT 0;
ALTER TABLE beam_course_revisions ADD COLUMN self_reviewed INTEGER NOT NULL DEFAULT 0;

-- OPS-001: how an audited change was made. NULL is the person's own signed-in
-- session; a change through an agent's preparation credential (BEAM-14) records
-- that credential's delegating session, so the audit names the agent route and
-- the person who delegated it. Corrections are appended as their own events.
ALTER TABLE beam_audit ADD COLUMN via TEXT;
CREATE INDEX beam_audit_subject ON beam_audit(action, subject);

-- AUTHOR-005 (retirement and cloning slice): a retired course keeps its
-- revisions, assignments, completions and certificates readable and its open
-- assignments completable, but no door assigns it anew until it is restored.
-- A clone records the course it was copied from.
ALTER TABLE beam_courses ADD COLUMN retired_at INTEGER;
ALTER TABLE beam_courses ADD COLUMN retired_by TEXT REFERENCES beam_members(id);
ALTER TABLE beam_courses ADD COLUMN retire_reason TEXT;
ALTER TABLE beam_courses ADD COLUMN cloned_from TEXT REFERENCES beam_courses(id);

-- AUTHOR-005 (catalog slice): how the course estate is organised. Folder,
