 INSERT OR IGNORE INTO beam_webhook_events VALUES('publication:'||NEW.id,'publication',NEW.id,NULL,NEW.course_id,NEW.id,'[]',json_object('course',NEW.course_id,'revision',NEW.id),NEW.reviewed_at);
END;
